use vstd::prelude::*;

verus! {
    /// Multiply the polynomial p(x) (given by its coefficient vector `c`)
    /// by x.  Concretely, if
    ///    p(x) = c[0] + c[1]·x + ⋯ + c[n−1]·xⁿ⁻¹
    /// then
    ///    x·p(x) =      0    + c[0]·x + ⋯ + c[n−1]·xⁿ
    fn legmulx(c: Vec<f32>) -> Vec<f32>
        ensures
            // The logical sequence of the result is [0.0] ++ c@
            result@ == Seq::unit(0.0) +++ c@,
    {
        // We know ahead of time that the result needs one more slot:
        let mut result = Vec::with_capacity(c.len() + 1);
        // The constant term of x·p(x) is 0.0
        result.push(0.0);
        // Now shift all the original coefficients “one place to the right”
        for coeff in c.into_iter() {
            result.push(coeff);
        }
        result
    }
}

